// Playground scenario bank — 100 high-difficulty AML/KYC decision scenarios.
// Each: situation → 4 options → correct answer + rationale.
// Difficulty 5 = genuinely ambiguous / senior-analyst level.

export interface PlaygroundScenario {
  id: number;
  cat: string;
  diff: 1 | 2 | 3 | 4 | 5;
  title: string;
  situation: string;
  options: [string, string, answer: string, string];
  answer: number;
  why: string;
}

